param(
 [ValidateSet('Scan','Plan','Apply','Locate','Report','InspectDownloads','InitPreview')][string]$Command,
 [string]$Root,[string[]]$Source,[string]$Query,[string]$PlanPath,[switch]$Authorize,[string]$ReportPath
)
$ErrorActionPreference='Stop'
$Cats=@{Software='01-Software';DeveloperTools='02-Developer-Tools';SourceCode='03-Source-Code';Documents='04-Documents';AIAssets='05-AI-Assets';Others='06-Others';Review='99-Review'}
$Partial=@('.crdownload','.part','.partial','.download','.tmp')
function Need($condition,$message){if(!$condition){throw $message}}
function SafeDir([string]$p){Need (Test-Path -LiteralPath $p -PathType Container) "Directory not found: $p";$i=Get-Item -LiteralPath $p -Force;Need (($i.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "Reparse point refused: $p";return (Resolve-Path -LiteralPath $p).Path.TrimEnd('\')}
function Classify($f){$n=$f.Name.ToLowerInvariant();$e=$f.Extension.ToLowerInvariant();if($n -match '(rust|cargo|rustup|sdk|compiler|toolchain|cli|^go[-_])'){return @('DeveloperTools','Name indicates developer tool')};if($e -in @('.zip','.7z','.tar','.gz') -and $n -match '(github|source|repo|repository|sample-project|example-project)'){return @('SourceCode','Archive name indicates source')};if($e -in @('.gguf','.safetensors','.ckpt') -or $n -match '(lora|checkpoint|dataset|model[-_])'){return @('AIAssets','Model/data indicator')};if($e -in @('.pdf','.doc','.docx','.xls','.xlsx','.ppt','.pptx','.epub','.mobi','.txt')){return @('Documents','Document format')};if($e -in @('.exe','.msi','.msix','.appx','.dmg','.pkg')){return @('Software','Installer format; purpose inferred from name/source')};if($e -in @('.jpg','.jpeg','.png','.gif','.webp','.mp3','.wav','.mp4','.mkv','.avi')){return @('Others','Media format')};if($e -in @('.zip','.7z','.rar','.tar','.gz')){return @('Review','Archive purpose ambiguous')};return @('Review','Insufficient purpose evidence')}
function ScanFiles([string[]]$paths){$out=@();foreach($p in $paths){$base=SafeDir $p;$stack=New-Object 'System.Collections.Generic.Stack[string]';$stack.Push($base);while($stack.Count){$d=$stack.Pop();foreach($i in Get-ChildItem -LiteralPath $d -Force -ErrorAction Stop){if($i.Attributes -band [IO.FileAttributes]::ReparsePoint){continue};if($i.PSIsContainer){$stack.Push($i.FullName);continue};if($Partial -contains $i.Extension.ToLowerInvariant()){continue};$c=Classify $i;$out+= [pscustomobject]@{Name=$i.Name;Source=$i.FullName;Bytes=$i.Length;Category=$c[0];Reason=$c[1];Complete=$true}}}};return ,$out}
function MakePlan([string[]]$paths,[string]$root){$r=[IO.Path]::GetFullPath($root);$out=@();foreach($f in (ScanFiles $paths)){$d=Join-Path (Join-Path $r $Cats[$f.Category]) $f.Name;$risk='None';if(Test-Path -LiteralPath $d){$f.Category='Review';$f.Reason='Destination conflict';$d=Join-Path (Join-Path $r $Cats.Review) $f.Name;$risk='Name conflict; no overwrite'};$f|Add-Member Destination $d;$f|Add-Member Risk $risk;$out+=$f};return ,$out}
function Envelope([string]$op,$items,[string[]]$errors=@(),[hashtable]$extra=@{}) { if($null -eq $items){$items=@()};$list=New-Object 'System.Collections.Generic.List[object]';foreach($x in $items){$list.Add($x)};$o=[ordered]@{schemaVersion=1;operation=$op;success=($errors.Count -eq 0);count=$list.Count;items=$list.ToArray();errors=@($errors)};foreach($k in $extra.Keys){$o[$k]=$extra[$k]};return [pscustomobject]$o }
Need $Command 'Command is required.'
switch($Command){
 Scan {Need $Source 'Scan requires -Source path(s).';$items=ScanFiles $Source;Envelope Scan $items|ConvertTo-Json -Depth 7 -Compress}
 Plan {Need ($Root -and $Source) 'Plan requires -Root and -Source.';$items=MakePlan $Source $Root;$p=if($PlanPath){$PlanPath}else{Join-Path $env:TEMP ('do-plan-'+[guid]::NewGuid()+'.json')};$envl=Envelope Plan $items;$envl|Add-Member planPath $p;$envl|ConvertTo-Json -Depth 7|Set-Content -LiteralPath $p -Encoding UTF8;$envl|ConvertTo-Json -Depth 7 -Compress}
 Apply {Need $Authorize 'Apply denied. Provide -Authorize only after approving the exact plan.';Need ($Root -and $PlanPath) 'Apply requires -Root and -PlanPath.';$saved=ConvertFrom-Json -InputObject (Get-Content -Raw $PlanPath);Need ($saved.schemaVersion -eq 1 -and $saved.operation -eq 'Plan' -and $saved.count -eq $saved.items.Count) 'Invalid plan data contract';$items=@($saved.items);$log=@();$errors=@();foreach($f in $items){$state='Failed';$err='';try{$src=(Resolve-Path -LiteralPath $f.Source -ErrorAction Stop).Path;$si=Get-Item -LiteralPath $src -Force;Need (($si.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) 'Source link refused';Need ($f.Name -notmatch '\.(crdownload|part|partial|download|tmp)$') 'Incomplete download refused';$r=[IO.Path]::GetFullPath($Root).TrimEnd('\')+'\';$dest=[IO.Path]::GetFullPath($f.Destination);Need $dest.StartsWith($r,[StringComparison]::OrdinalIgnoreCase) 'Destination outside selected root';Need !(Test-Path -LiteralPath $dest) 'Destination exists; no overwrite';$null=SafeDir (Split-Path $src -Parent);$null=New-Item -ItemType Directory -Path (Split-Path $dest -Parent) -Force;$same=[IO.Path]::GetPathRoot($src) -eq [IO.Path]::GetPathRoot($dest);if($same){[IO.File]::Move($src,$dest);$state='Moved'}else{$tmp=$dest+'.verify-'+[guid]::NewGuid().ToString('N');Copy-Item -LiteralPath $src -Destination $tmp -ErrorAction Stop;$a=(Get-FileHash $src -Algorithm SHA256).Hash;$b=(Get-FileHash $tmp -Algorithm SHA256).Hash;Need ($a -eq $b) 'Cross-volume verification failed; source retained';[IO.File]::Move($tmp,$dest);$state='Copied'}}catch{$err=$_.Exception.Message;$errors+=$err};$log+= [pscustomobject]@{Source=$f.Source;Destination=$f.Destination;Status=$state;Error=$err}};$op=Envelope Apply $log $errors;$logPath=$PlanPath+'.operations.json';$all=@($log);$allErrors=@($errors);if(Test-Path $logPath){$prior=ConvertFrom-Json -InputObject (Get-Content -Raw $logPath);$all=@($prior.items)+@($log);$allErrors=@($prior.errors)+@($errors)};$history=Envelope Apply $all $allErrors;$history|ConvertTo-Json -Depth 7|Set-Content -LiteralPath $logPath -Encoding UTF8;$op|ConvertTo-Json -Depth 7 -Compress}
 Locate {Need ($Root -and $Query) 'Locate requires -Root and -Query.';$hits=@(ScanFiles @($Root)|Where-Object{$_.Name -like "*$Query*" -or $_.Category -like "*$Query*"});$e=Envelope Locate $hits;if(!$hits){$e|Add-Member message 'No matching files found'};$e|ConvertTo-Json -Depth 7 -Compress}
 Report {Need $PlanPath 'Report requires -PlanPath.';$doc=ConvertFrom-Json -InputObject (Get-Content -Raw $PlanPath);Need ($doc.schemaVersion -eq 1 -and $doc.operation -eq 'Plan' -and $doc.count -eq $doc.items.Count) 'Invalid plan data contract';$items=@($doc.items);[long]$total=0;foreach($f in $items){if($null -eq $f.PSObject.Properties['Bytes']){throw 'Invalid report item: Bytes is missing'};[long]$b=0;if(-not [long]::TryParse([string]$f.Bytes,[ref]$b) -or $b -lt 0){throw 'Invalid report item: Bytes must be nonnegative Int64'};$total+=$b};$opPath=$PlanPath+'.operations.json';$ops=@();if(Test-Path $opPath){$od=ConvertFrom-Json -InputObject (Get-Content -Raw $opPath);if($od.items){$ops=@($od.items)}};$rev=@($items|Where-Object Category -eq Review).Count;$organized=@($ops|Where-Object Status -in @('Moved','Copied')).Count;$failed=@($ops|Where-Object Status -eq Failed).Count;$reportFile=if($ReportPath){$ReportPath}else{$PlanPath+'.md'};$extra=@{totalBytes=$total;review=$rev;organized=$organized;failed=$failed;markdownPath=$reportFile};$out=Envelope Report $items @() $extra;$md=@('# Download Organizer report','',"- Scanned: $($out.count)","- Classified: $($out.count-$rev)","- Review: $rev","- Organized: $organized","- Failed: $failed","- Total bytes: $total",'','## Files');foreach($f in $items){$md+="- $($f.Source) -> $($f.Destination) [$($f.Category)] $($f.Bytes) bytes"};$md|Set-Content -LiteralPath $reportFile -Encoding UTF8;$out|ConvertTo-Json -Depth 7 -Compress}
 InspectDownloads {$src='using System; using System.Runtime.InteropServices; public static class KnownFolder { [DllImport("shell32.dll", CharSet=CharSet.Unicode)] public static extern int SHGetKnownFolderPath([MarshalAs(UnmanagedType.LPStruct)] Guid id,uint flags,IntPtr token,out IntPtr path); }';Add-Type -TypeDefinition $src -ErrorAction Stop;$ptr=[IntPtr]::Zero;$hr=[KnownFolder]::SHGetKnownFolderPath([guid]'374DE290-123F-4565-9164-39C4925E467B',0,[IntPtr]::Zero,[ref]$ptr);Need ($hr -eq 0) "SHGetKnownFolderPath failed HRESULT=$hr";try{$p=[Runtime.InteropServices.Marshal]::PtrToStringUni($ptr);Need $p 'Known Folder returned an empty path';Need (Test-Path -LiteralPath $p -PathType Container) "Known Downloads folder does not exist: $p";$o=Envelope InspectDownloads @() @() @{windowsDownloads=$p;organizerRoot='Not inferred; select separately'};$o|ConvertTo-Json -Depth 5 -Compress}finally{if($ptr -ne [IntPtr]::Zero){[Runtime.InteropServices.Marshal]::FreeCoTaskMem($ptr)}}}
 InitPreview {Need $Root 'InitPreview requires -Root.';$p=[IO.Path]::GetFullPath((Join-Path $Root '00-Inbox'));$o=Envelope InitPreview @() @() @{organizerRoot=[IO.Path]::GetFullPath($Root);proposedWindowsDownloads=$p;exists=(Test-Path -LiteralPath $p);modified=$false};$o|ConvertTo-Json -Depth 5 -Compress}
}

